  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-indic: 'Noto Sans', 'Noto Sans Ol Chiki', system-ui, sans-serif;
  --transition-fast: 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  --transition-smooth: 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-slate);
  color: var(--text-body);
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* Indic Script Font Classes */
.indic-text, .script-text {
  font-family: var(--font-indic);
}

/* Tribal Sohrai/Khovar Background Motif */
.tribal-pattern-bg {
  background-image: 
    radial-gradient(var(--border-subtle) 1px, transparent 1px),
    linear-gradient(to right, rgba(255, 103, 31, 0.02) 1px, transparent 1px);
  background-size: 24px 24px, 48px 48px;
}

.tribal-border-top {
  position: relative;
}
.tribal-border-top::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 6px;
  background: repeating-linear-gradient(
    45deg,
    var(--accent-saffron),
    var(--accent-saffron) 10px,
    var(--bg-white) 10px,
    var(--bg-white) 14px,
    var(--accent-green) 14px,
    var(--accent-green) 24px,
    var(--primary-navy) 24px,
    var(--primary-navy) 34px
  );
}

/* Container */
.container {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Typography & Section Titles */
.section-tag {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  color: var(--accent-saffron);
  background-color: var(--accent-saffron-light);
  padding: 6px 14px;
  border-radius: var(--radius-full);
  margin-bottom: 14px;
  border: 1px solid rgba(255, 103, 31, 0.2);
}

.section-tag.green {
  color: var(--accent-green);
  background-color: var(--accent-green-light);
  border-color: rgba(4, 120, 87, 0.2);
}

.section-tag.navy {
  color: var(--primary-navy);
  background-color: rgba(10, 37, 64, 0.06);
  border-color: rgba(10, 37, 64, 0.15);
}

.section-title {
  font-size: 2.35rem;
  font-weight: 800;
  color: var(--primary-navy);
  line-height: 1.25;
  letter-spacing: -0.5px;
  margin-bottom: 12px;
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--text-muted);
  max-width: 720px;
  margin-bottom: 40px;
}

.text-center {
  text-align: center;
}
.text-center .section-subtitle {
  margin-left: auto;
  margin-right: auto;
}

/* ==========================================================================
   Navbar
   ========================================================================== */
.navbar {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border-subtle);
  transition: all var(--transition-fast);
}

.navbar.scrolled {
  box-shadow: var(--shadow-sm);
  background: rgba(255, 255, 255, 0.98);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.brand-logo {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
}

.brand-symbol {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: linear-gradient(135deg, var(--primary-navy) 0%, #173860 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 22px;
  box-shadow: 0 4px 10px rgba(10, 37, 64, 0.25);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.brand-text {
  display: flex;
  flex-direction: column;
}

.brand-name {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--primary-navy);
  letter-spacing: -0.3px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.brand-name .ai-badge {
  font-size: 0.68rem;
  padding: 2px 6px;
  background: linear-gradient(90deg, var(--accent-saffron), #FF8533);
  color: #fff;
  border-radius: 4px;
  font-weight: 700;
}

.brand-sub {
  font-size: 0.7rem;
  color: var(--text-muted);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 24px;
  list-style: none;
}

.nav-links a {
  text-decoration: none;
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--text-body);
  transition: color var(--transition-fast);
  position: relative;
}

.nav-links a:hover, .nav-links a.active {
  color: var(--accent-saffron);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 14px;
}

.lang-toggle-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: var(--bg-slate);
  border: 1.5px solid var(--border-subtle);
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--primary-navy);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.lang-toggle-btn:hover {
  border-color: var(--accent-saffron);
  background: var(--accent-saffron-light);
  color: var(--accent-saffron);
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 22px;
  background: linear-gradient(135deg, var(--accent-saffron) 0%, #E85507 100%);
  color: #fff;
  font-size: 0.92rem;
  font-weight: 700;
  border-radius: var(--radius-md);
  text-decoration: none;
  border: none;
  cursor: pointer;
  box-shadow: 0 4px 14px rgba(255, 103, 31, 0.35);
  transition: all var(--transition-fast);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(255, 103, 31, 0.45);
}

.btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 22px;
  background: #FFFFFF;
  color: var(--primary-navy);
  font-size: 0.92rem;
  font-weight: 700;
  border-radius: var(--radius-md);
  text-decoration: none;
  border: 1.5px solid var(--border-subtle);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.btn-secondary:hover {
  border-color: var(--primary-navy);
  background: var(--bg-slate);
  transform: translateY(-2px);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  font-size: 1.6rem;
  color: var(--primary-navy);
  cursor: pointer;
}

/* ==========================================================================
   Hero Section
   ========================================================================== */
.hero-section {
  position: relative;
  padding: 64px 0 40px;
  background: linear-gradient(180deg, #FFFFFF 0%, #F1F5F9 100%);
  overflow: hidden;
}

.hero-govt-badge {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: #FFFFFF;
  padding: 8px 18px;
  border-radius: var(--radius-full);
  border: 1.5px solid rgba(10, 37, 64, 0.12);
  box-shadow: var(--shadow-sm);
  margin-bottom: 24px;
}

.govt-emblem {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--accent-green);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 11px;
  font-weight: 900;
}

.govt-text {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--primary-navy);
}

.hero-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 48px;
  align-items: center;
}

.hero-content h1 {
  font-size: 3.4rem;
  font-weight: 900;
  color: var(--primary-navy);
  line-height: 1.12;
  letter-spacing: -1.2px;
  margin-bottom: 12px;
}

.hero-content .highlight {
  background: linear-gradient(120deg, var(--accent-saffron), #FF8A00);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.hero-tagline {
  font-size: 1.45rem;
  font-weight: 700;
  color: var(--accent-green);
  margin-bottom: 18px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.hero-desc {
  font-size: 1.15rem;
  color: var(--text-body);
  line-height: 1.7;
  margin-bottom: 28px;
  max-width: 620px;
}

.hero-alt-names {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 32px;
}

.alt-label {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
}

.name-pill {
  padding: 4px 12px;
  background: #FFFFFF;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-full);
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--primary-navy);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.name-pill.active, .name-pill:hover {
  background: var(--primary-navy);
  color: #fff;
  border-color: var(--primary-navy);
}

.hero-cta-group {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 40px;
}

.hero-stats-row {
  display: flex;
  gap: 32px;
  padding-top: 24px;
  border-top: 1px solid var(--border-subtle);
}

.hero-stat-item {
  display: flex;
  flex-direction: column;
}

.stat-val {
  font-size: 1.85rem;
  font-weight: 900;
  color: var(--primary-navy);
  line-height: 1.1;
}

.stat-lbl {
  font-size: 0.8rem;
  color: var(--text-muted);
  font-weight: 600;
}

/* Hero Right Visual Card */
.hero-visual-card {
  position: relative;
  background: #FFFFFF;
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--border-subtle);
}

.classroom-sim-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 14px;
  margin-bottom: 16px;
  border-bottom: 1px solid var(--border-subtle);
}

.sim-tag {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--accent-green);
}

.pulse-dot {
  width: 8px;
  height: 8px;
  background: var(--accent-green);
  border-radius: 50%;
  animation: pulse 1.8s infinite;
}

@keyframes pulse {
  0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(4, 120, 87, 0.7); }
  70% { transform: scale(1); box-shadow: 0 0 0 8px rgba(4, 120, 87, 0); }
  100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(4, 120, 87, 0); }
}

.teacher-bubble {
  background: #F1F5F9;
  border-radius: 14px 14px 14px 2px;
  padding: 14px 18px;
  margin-bottom: 16px;
  border-left: 4px solid var(--primary-navy);
}

.bubble-sender {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--primary-navy);
  text-transform: uppercase;
  margin-bottom: 4px;
}

.bubble-content {
  font-size: 0.95rem;
  color: var(--text-dark);
  font-weight: 500;
}

.ai-bridge-flow {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin: 16px 0;
  padding: 10px;
  background: var(--accent-saffron-light);
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--accent-saffron);
}

.student-bubble {
  background: #ECFDF5;
  border-radius: 14px 14px 2px 14px;
  padding: 14px 18px;
  border-right: 4px solid var(--accent-green);
}

.student-bubble .bubble-sender {
  color: var(--accent-green);
  text-align: right;
}

.student-bubble .bubble-content {
  font-family: var(--font-indic);
  font-size: 1.05rem;
  color: #064E3B;
  font-weight: 600;
}

.student-phonetic {
  font-size: 0.8rem;
  color: #047857;
  font-style: italic;
  margin-top: 4px;
  text-align: right;
}

/* ==========================================================================
   Animated Language Script Marquee
   ========================================================================== */
.script-marquee-wrapper {
  background: var(--primary-navy);
  color: #fff;
  padding: 14px 0;
  overflow: hidden;
  position: relative;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.marquee-track {
  display: flex;
  width: max-content;
  animation: scrollMarquee 35s linear infinite;
  gap: 40px;
}

.marquee-item {
  display: flex;
  align-items: center;
  gap: 12px;
  white-space: nowrap;
  font-size: 0.95rem;
}

.marquee-lang {
  padding: 2px 8px;
  background: rgba(255, 255, 255, 0.15);
  border-radius: 4px;
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--accent-saffron);
}

.marquee-phrase {
  font-family: var(--font-indic);
  font-weight: 500;
}

.marquee-sep {
  color: rgba(255, 255, 255, 0.3);
}

@keyframes scrollMarquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

.script-marquee-wrapper:hover .marquee-track {
  animation-play-state: paused;
}
