/* ==========================================================================
   Problem Section
   ========================================================================== */
.problem-section {
  padding: 88px 0;
  background-color: var(--bg-white);
  border-bottom: 1px solid var(--border-subtle);
}

.narrative-box {
  background: linear-gradient(135deg, #FFF7ED 0%, #FFFBEB 100%);
  border-left: 5px solid var(--accent-saffron);
  padding: 24px 28px;
  border-radius: var(--radius-md);
  margin-bottom: 48px;
}

.narrative-title {
  font-size: 1.15rem;
  font-weight: 800;
  color: #9A3412;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.narrative-text {
  font-size: 1rem;
  color: #7C2D12;
  line-height: 1.7;
}

.stats-grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.stat-card {
  background: var(--bg-slate);
  padding: 28px 22px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-subtle);
  transition: all var(--transition-smooth);
  position: relative;
  overflow: hidden;
}

.stat-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: var(--primary-navy-light);
}

.stat-card-number {
  font-size: 2.5rem;
  font-weight: 900;
  color: var(--primary-navy);
  line-height: 1;
  margin-bottom: 10px;
}

.stat-card.saffron .stat-card-number {
  color: var(--accent-saffron);
}

.stat-card.green .stat-card-number {
  color: var(--accent-green);
}

.stat-card-label {
  font-size: 0.95rem;
  font-weight: 800;
  color: var(--text-dark);
  margin-bottom: 8px;
}

.stat-card-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
  line-height: 1.5;
}

/* ==========================================================================
   Solution Section
   ========================================================================== */
.solution-section {
  padding: 88px 0;
  background-color: var(--bg-slate);
  border-bottom: 1px solid var(--border-subtle);
}

.solution-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 28px;
}

.solution-card {
  background: var(--bg-white);
  padding: 32px 28px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-subtle);
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-smooth);
  display: flex;
  gap: 20px;
}

.solution-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: rgba(255, 103, 31, 0.4);
}

.solution-icon-box {
  width: 56px;
  height: 56px;
  min-width: 56px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  background: var(--accent-saffron-light);
  color: var(--accent-saffron);
}

.solution-card:nth-child(2) .solution-icon-box {
  background: var(--accent-green-light);
  color: var(--accent-green);
}

.solution-card:nth-child(3) .solution-icon-box {
  background: #EFF6FF;
  color: #2563EB;
}

.solution-card:nth-child(4) .solution-icon-box {
  background: #FDF2F8;
  color: #DB2777;
}

.solution-card-body h3 {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--primary-navy);
  margin-bottom: 8px;
}

.solution-card-body p {
  font-size: 0.95rem;
  color: var(--text-body);
  line-height: 1.6;
}

/* ==========================================================================
   LIVE INTERACTIVE DEMO (Core Hackathon Showcase)
   ========================================================================== */
.demo-section {
  padding: 92px 0;
  background: linear-gradient(180deg, #FFFFFF 0%, #EEF4F8 100%);
  position: relative;
  border-bottom: 1px solid var(--border-subtle);
}

.demo-container {
  background: #FFFFFF;
  border-radius: 24px;
  border: 1.5px solid var(--border-subtle);
  box-shadow: var(--shadow-xl);
  overflow: hidden;
}

/* Demo Control Bar */
.demo-top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 28px;
  background: var(--primary-navy);
  color: #fff;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  flex-wrap: wrap;
  gap: 16px;
}

.demo-title-group {
  display: flex;
  align-items: center;
  gap: 12px;
}

.demo-chip {
  padding: 4px 10px;
  background: var(--accent-saffron);
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.demo-mode-switcher {
  display: flex;
  align-items: center;
  gap: 12px;
  background: rgba(255, 255, 255, 0.1);
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 600;
}

/* Toggle Switch UI */
.switch {
  position: relative;
  display: inline-block;
  width: 52px;
  height: 26px;
}

.switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--accent-green);
  transition: .3s;
  border-radius: 34px;
}

.slider:before {
  position: absolute;
  content: "";
  height: 20px;
  width: 20px;
  left: 3px;
  bottom: 3px;
  background-color: white;
  transition: .3s;
  border-radius: 50%;
}

input:checked + .slider {
  background-color: var(--accent-saffron);
}

input:checked + .slider:before {
  transform: translateX(26px);
}

/* Mode Notification Banner */
.demo-mode-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 28px;
  font-size: 0.85rem;
  font-weight: 600;
  transition: all var(--transition-fast);
}

.demo-mode-banner.offline {
  background: #ECFDF5;
  color: #065F46;
  border-bottom: 1px solid #A7F3D0;
}

.demo-mode-banner.online {
  background: #EFF6FF;
  color: #1E40AF;
  border-bottom: 1px solid #BFDBFE;
}

.bandwidth-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border-radius: 6px;
  font-weight: 700;
  font-size: 0.78rem;
  background: rgba(0, 0, 0, 0.06);
}

/* Preset Buttons Bar */
.demo-presets-row {
  padding: 18px 28px;
  background: #F8FAFC;
  border-bottom: 1px solid var(--border-subtle);
}

.preset-heading {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.preset-buttons-container {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.preset-btn {
  padding: 7px 14px;
  background: #FFFFFF;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--text-dark);
  cursor: pointer;
  transition: all var(--transition-fast);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.preset-btn:hover, .preset-btn.active {
  border-color: var(--accent-saffron);
  background: var(--accent-saffron-light);
