/* Demo Workspace Layout (Input | Output) */
.demo-workspace {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 480px;
}

.demo-input-panel {
  padding: 28px;
  border-right: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
}

.demo-output-panel {
  padding: 28px;
  background: #FAFAFC;
  display: flex;
  flex-direction: column;
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.panel-label {
