  cursor: pointer;
  outline: none;
  transition: border var(--transition-fast);
}

.lang-select:focus {
  border-color: var(--accent-saffron);
}

/* Text Input & Mic Area */
.input-field-wrapper {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  margin-bottom: 18px;
}

.demo-textarea {
  width: 100%;
  flex: 1;
  min-height: 180px;
  padding: 16px;
  border: 1.5px solid var(--border-subtle);
  border-radius: var(--radius-md);
  font-family: var(--font-indic);
  font-size: 1.05rem;
  color: var(--text-dark);
  line-height: 1.6;
  resize: none;
  outline: none;
  transition: border-color var(--transition-fast);
}

.demo-textarea:focus {
  border-color: var(--accent-saffron);
  box-shadow: 0 0 0 3px rgba(255, 103, 31, 0.12);
}

.mic-action-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 8px;
}

.mic-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  background: var(--bg-slate);
  border: 1.5px solid var(--border-subtle);
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--primary-navy);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.mic-btn:hover {
  background: #FEE2E2;
  border-color: #EF4444;
  color: #DC2626;
}

.mic-btn.recording {
  background: #EF4444;
  color: #fff;
  border-color: #DC2626;
  animation: pulse-red 1.2s infinite;
}

@keyframes pulse-red {
  0% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.7); }
  70% { box-shadow: 0 0 0 10px rgba(239, 68, 68, 0); }
  100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); }
}

.char-counter {
  font-size: 0.78rem;
  color: var(--text-muted);
}

/* Live Speech Waveform Visualizer */
.soundwave-box {
  display: none;
  align-items: center;
  gap: 4px;
  height: 24px;
}

.soundwave-box.active {
  display: flex;
}

.wave-bar {
  width: 3px;
  height: 8px;
  background: #EF4444;
  border-radius: 2px;
  animation: wave 0.8s ease-in-out infinite alternate;
}
.wave-bar:nth-child(2) { animation-delay: 0.15s; }
.wave-bar:nth-child(3) { animation-delay: 0.3s; }
.wave-bar:nth-child(4) { animation-delay: 0.45s; }
.wave-bar:nth-child(5) { animation-delay: 0.6s; }

@keyframes wave {
  0% { height: 4px; }
  100% { height: 20px; }
}

/* Translate Main Button */
.btn-translate {
